constraints:
1 <= L <= R <= 10^{9}

expected time complexity: O(sqrt(R)*log(R))
expected auxiliary space: O(sqrt(R))

standard_solution_code:
class Solution:

	def count3DivNums(self, L, R):

		def isPrime(n):
			if n == 1:
				return False
			else:
				lim = int(n ** 0.5) + 1
				for i in range(2, lim):
					if n % i == 0:
						return False
				return True
		c = 0
		if L ** 0.5 == int(L ** 0.5):
			s = int(L ** 0.5)
		else:
			s = int(L ** 0.5) + 1
		e = int(R ** 0.5) + 1
		for i in range(s, e):
			if isPrime(i):
				c += 1
		return c
